def collect(mon):
    topology=mon('osd dump');usage=mon('df',detail='detail')
    stats=usage['stats'];total=stats['total_bytes'];used=stats['total_used_raw_bytes']
    if not total:raise ValueError('native capacity statistics not ready')
    full=sorted(x['osd']for x in topology['osds']if 'full'in x['state'])
    pool_stats={x['id']:x['stats']for x in usage['pools']};pools=[]
    for pool in sorted(topology['pools'],key=lambda x:x['pool_name']):
        quota='full_quota'in pool['flags_names'].split(',');physical=bool(full);data=pool_stats[pool['pool']]
        gate='pool_quota_and_osd_full'if quota and physical else 'pool_quota'if quota else 'osd_full'if physical else 'open'
        pools.append(dict(name=pool['pool_name'],id=pool['pool'],quota_max_objects=pool['quota_max_objects'],quota_max_bytes=pool['quota_max_bytes'],
            objects=data['objects'],logical_stored_bytes=data['stored'],quota_full=quota,underlying_full=physical,write_gate=gate))
    return dict(raw_total_bytes=total,raw_used_bytes=used,raw_used_ratio=used/total,nearfull_ratio=topology['nearfull_ratio'],
        backfillfull_ratio=topology['backfillfull_ratio'],full_ratio=topology['full_ratio'],full_osd_ids=full,pools=pools,pool_quota_is_cluster_capacity_guard=False)

